         "yakh": "ice (yakh kardan = to freeze)",
         "kardim": "we did",
         "vali": "but",
         "baadesh": "afterwards (spoken)",
         "tu": "in (spoken)",
         "ye": "a (spoken for yek)",
         "ghahvekhune": "teahouse (spoken for ghahvekhaane)",
         "chaay-e": "tea (ezafe)",
         "daagh": "hot",
         "khordim": "we drank, had",
         "kheyli": "very",
         "chasbid": "hit the spot (lit. stuck)"
